B.Ze=new A.e2("p1b_mcq1","rbb_it_5",B.bG,B.hp,1,"IT Fundamentals",1,B.co,B.T5,"RAM \u0915\u094b \u092a\u0942\u0930\u094d\u0923 \u0930\u0942\u092a \u0915\u0947 \u0939\u094b?","What is the full form of RAM?",null,null,B.TF,0,"RAM stands for Random Access Memory \u2014 volatile memory used for temporary data storage while the CPU processes it.",!1)
